submissionValidations:
if(
    budget_actual > budget_planned * 2,
    'Actual spend is more than double the plan (' + budget_actual + ' vs ' + budget_planned + ') — please review before submitting.',
    null
)

if(
    invoices_paid_on_time_pct < 100 and overdue_invoices_count == 0,
    'Inconsistent: payment-on-time rate is below 100% but no overdue invoices were recorded.',
    null
)

if(
    revenue_collected > revenue_target * 3,
    'Reported revenue is more than three times the target. Looks like a unit/currency mistake — please re-check.',
    null
)

values.warning:
if(
    budget_planned > 0 and budget_actual > budget_planned * 1.25,
    'Actual spend is more than 25% above plan — flag for the variance review.',
    null
)

if(
    revenue_target > 0 and revenue_collected < revenue_target * 0.75,
    'Revenue is below 75% of target — flag for the finance committee briefing.',
    null
)
